/**
 * Garba Audio Engine:
 * - Real YouTube iFrame Player integration
 * - Procedural Web Audio API Synthesizer (Dhol, Manjira, Dandiya Clack, Tanpura Drone)
 * - Synchronized BPM Beat Clock for 3D Dancers & Visualizers
 */

class GarbaAudioEngine {
  constructor() {
    this.ctx = null;
    this.ytPlayer = null;
    this.ytReady = false;
    this.currentTrack = null;
    this.isPlaying = false;
    this.isMuted = false;
    this.volume = 0.85;

    // Callbacks
    this.onPlayStateChange = null;
    this.onTimeUpdate = null;
    this.onBeat = null;
    this.onTrackEnded = null;

    // Beat clock
    this.bpm = 118;
    this.beatIndex = 0;
    this.lastBeatTime = 0;
    this.beatInterval = 60 / this.bpm;
    this.timerId = null;

    // Tanpura Drone Nodes
    this.tanpuraGain = null;
    this.tanpuraOscs = [];

    // Synthesizer Noise Buffer Cache
    this.noiseBuffer = null;

    // Track simulated progress when YouTube is streaming or offline
    this.currentTime = 0;
    this.duration = 300;
  }

  init() {
    const AudioContextClass = window.AudioContext || window.webkitAudioContext;
    if (AudioContextClass && !this.ctx) {
      this.ctx = new AudioContextClass();
    }
  }

  ensureContext() {
    this.init();
    if (this.ctx && this.ctx.state === 'suspended') {
      this.ctx.resume();
    }
  }

  getNoiseBuffer() {
    if (!this.ctx) return null;
    if (this.noiseBuffer) return this.noiseBuffer;
    const len = this.ctx.sampleRate * 1.5;
    const buf = this.ctx.createBuffer(1, len, this.ctx.sampleRate);
    const data = buf.getChannelData(0);
    for (let i = 0; i < len; i++) {
      data[i] = Math.random() * 2 - 1;
    }
    this.noiseBuffer = buf;
    return buf;
  }

  /* ─────────────────────────────────────────────────────────────
     Procedural Sound Effects
     ───────────────────────────────────────────────────────────── */

  /**
   * Authentic Gujarati Dhol strike
   * Left head (Dhama - deep pitch-dropped bass skin) + Right head (Thapi - crisp slap)
   */
  playDhol(gainVal = 0.6) {
    if (this.isMuted) return;
    this.ensureContext();
    if (!this.ctx) return;

    const t = this.ctx.currentTime;

    // 1. Left Bass Head (Dhama)
    const osc = this.ctx.createOscillator();
    const oscGain = this.ctx.createGain();

    osc.type = 'sine';
    // Pitch drops rapidly as struck leather membrane settles
    osc.frequency.setValueAtTime(140, t);
    osc.frequency.exponentialRampToValueAtTime(42, t + 0.12);

    oscGain.gain.setValueAtTime(gainVal * 0.9, t);
    oscGain.gain.exponentialRampToValueAtTime(0.001, t + 0.38);

    osc.connect(oscGain);
    oscGain.connect(this.ctx.destination);
    osc.start(t);
    osc.stop(t + 0.4);

    // 2. Right Treble Head (Thapi / Snare resonance)
    const noise = this.getNoiseBuffer();
    if (noise) {
      const src = this.ctx.createBufferSource();
      src.buffer = noise;

      const filter = this.ctx.createBiquadFilter();
      filter.type = 'bandpass';
      filter.frequency.setValueAtTime(950, t);
      filter.Q.setValueAtTime(2.8, t);

      const slapGain = this.ctx.createGain();
      slapGain.gain.setValueAtTime(gainVal * 0.45, t);
      slapGain.gain.exponentialRampToValueAtTime(0.001, t + 0.12);

      src.connect(filter);
      filter.connect(slapGain);
      slapGain.connect(this.ctx.destination);

      src.start(t);
      src.stop(t + 0.15);
    }
  }

  /**
   * Authentic Brass Manjira chime (high ringing overtones)
   */
  playManjira(gainVal = 0.5) {
    if (this.isMuted) return;
    this.ensureContext();
    if (!this.ctx) return;

    const t = this.ctx.currentTime;
    const freqs = [2380, 3620, 5240];

    freqs.forEach((freq, idx) => {
      const osc = this.ctx.createOscillator();
      const g = this.ctx.createGain();
      osc.type = 'sine';
      osc.frequency.setValueAtTime(freq, t);

      const decay = 0.35 + idx * 0.15;
      g.gain.setValueAtTime(gainVal * 0.25, t);
      g.gain.exponentialRampToValueAtTime(0.0001, t + decay);

      osc.connect(g);
      g.connect(this.ctx.destination);
      osc.start(t);
      osc.stop(t + decay);
    });
  }

  /**
   * Wooden Dandiya stick clash sound
   */
  playDandiya(gainVal = 0.5) {
    if (this.isMuted) return;
    this.ensureContext();
    if (!this.ctx) return;

    const t = this.ctx.currentTime;

    // Resonant wooden body
    const osc = this.ctx.createOscillator();
    const g = this.ctx.createGain();
    osc.type = 'triangle';
    osc.frequency.setValueAtTime(1240, t);
    osc.frequency.exponentialRampToValueAtTime(320, t + 0.05);

    g.gain.setValueAtTime(gainVal * 0.8, t);
    g.gain.exponentialRampToValueAtTime(0.001, t + 0.08);

    osc.connect(g);
    g.connect(this.ctx.destination);
    osc.start(t);
    osc.stop(t + 0.09);

    // High wood click
    const noise = this.getNoiseBuffer();
    if (noise) {
      const src = this.ctx.createBufferSource();
      src.buffer = noise;
      const f = this.ctx.createBiquadFilter();
      f.type = 'highpass';
      f.frequency.setValueAtTime(2200, t);

      const ng = this.ctx.createGain();
      ng.gain.setValueAtTime(gainVal * 0.5, t);
      ng.gain.exponentialRampToValueAtTime(0.001, t + 0.04);

      src.connect(f);
      f.connect(ng);
      ng.connect(this.ctx.destination);
      src.start(t);
      src.stop(t + 0.05);
    }
  }

  /**
   * Start holy ambient Tanpura drone bed
   */
  startTanpuraDrone(targetGain = 0.035) {
    this.ensureContext();
    if (!this.ctx) return;
    if (this.tanpuraGain) return; // already active

    const t = this.ctx.currentTime;
    this.tanpuraGain = this.ctx.createGain();
    this.tanpuraGain.gain.setValueAtTime(0.0001, t);
    this.tanpuraGain.gain.linearRampToValueAtTime(targetGain, t + 2);
    this.tanpuraGain.connect(this.ctx.destination);

    // Indian classical Sa-Pa harmony (C# drone root: ~138.59 Hz, Pa fifth: ~207.65 Hz)
    const baseFreqs = [138.59, 207.65, 277.18, 415.30];
    this.tanpuraOscs = baseFreqs.map((f, i) => {
      const osc = this.ctx.createOscillator();
      osc.type = i % 2 === 0 ? 'sine' : 'triangle';
      osc.frequency.setValueAtTime(f + (Math.random() - 0.5) * 0.4, t);
      osc.connect(this.tanpuraGain);
      osc.start(t);
      return osc;
    });
  }

  stopTanpuraDrone() {
    if (!this.tanpuraGain || !this.ctx) return;
    const t = this.ctx.currentTime;
    this.tanpuraGain.gain.linearRampToValueAtTime(0.0001, t + 1);
    setTimeout(() => {
      this.tanpuraOscs.forEach((o) => {
        try { o.stop(); } catch (e) {}
      });
      this.tanpuraOscs = [];
      this.tanpuraGain = null;
    }, 1100);
  }

  /* ─────────────────────────────────────────────────────────────
     YouTube Player Integration
     ───────────────────────────────────────────────────────────── */

  mountYouTubePlayer(containerId, onReadyCallback) {
    if (window.YT && window.YT.Player) {
      this.createYTPlayer(containerId, onReadyCallback);
      return;
    }

    // Inject YouTube IFrame API script
    const tag = document.createElement('script');
    tag.src = 'https://www.youtube.com/iframe_api';
    const firstScriptTag = document.getElementsByTagName('script')[0];
    firstScriptTag.parentNode.insertBefore(tag, firstScriptTag);

    window.onYouTubeIframeAPIReady = () => {
      this.createYTPlayer(containerId, onReadyCallback);
    };
  }

  createYTPlayer(containerId, onReadyCallback) {
    this.ytPlayer = new window.YT.Player(containerId, {
      height: '1',
      width: '1',
      videoId: 'fPgqCMnhTNM',
      playerVars: {
        autoplay: 0,
        controls: 0,
        disablekb: 1,
        enablejsapi: 1,
        fs: 0,
        modestbranding: 1,
        playsinline: 1,
        rel: 0,
        origin: window.location.origin
      },
      events: {
        onReady: (event) => {
          this.ytReady = true;
          if (onReadyCallback) onReadyCallback();
        },
        onStateChange: (event) => {
          // YT.PlayerState: -1 (unstarted), 0 (ended), 1 (playing), 2 (paused), 3 (buffering), 5 (cued)
          if (event.data === window.YT.PlayerState.PLAYING) {
            this.setPlayingState(true);
          } else if (event.data === window.YT.PlayerState.PAUSED) {
            this.setPlayingState(false);
          } else if (event.data === window.YT.PlayerState.ENDED) {
            if (this.onTrackEnded) this.onTrackEnded();
          }
        },
        onError: (err) => {
          console.warn('YouTube stream notice, continuing with Garba procedural audio:', err);
          // Don't crash; procedural engine continues seamlessly
        }
      }
    });
  }

  /* ─────────────────────────────────────────────────────────────
     Playback Control
     ───────────────────────────────────────────────────────────── */

  loadTrack(track, autoPlay = true) {
    this.currentTrack = track;
    this.bpm = track.bpm || 118;
    this.duration = track.duration || 300;
    this.currentTime = 0;
    this.beatInterval = 60 / this.bpm;

    if (this.ytReady && this.ytPlayer && this.ytPlayer.loadVideoById) {
      try {
        if (autoPlay) {
          this.ytPlayer.loadVideoById(track.id);
        } else {
          this.ytPlayer.cueVideoById(track.id);
        }
      } catch (e) {
        console.warn('YT cue error', e);
      }
    }

    if (autoPlay) {
      this.play();
    }
  }

  play() {
    this.ensureContext();
    this.startTanpuraDrone();
    this.startBeatClock();

    if (this.ytReady && this.ytPlayer && this.ytPlayer.playVideo) {
      try {
        this.ytPlayer.playVideo();
      } catch (e) {}
    }
    this.setPlayingState(true);
  }

  pause() {
    if (this.ytReady && this.ytPlayer && this.ytPlayer.pauseVideo) {
      try {
        this.ytPlayer.pauseVideo();
      } catch (e) {}
    }
    this.setPlayingState(false);
    this.stopTanpuraDrone();
    this.stopBeatClock();
  }

  togglePlay() {
    if (this.isPlaying) {
      this.pause();
    } else {
      this.play();
    }
    return this.isPlaying;
  }

  seekTo(seconds) {
    this.currentTime = Math.max(0, Math.min(this.duration, seconds));
    if (this.ytReady && this.ytPlayer && this.ytPlayer.seekTo) {
      try {
        this.ytPlayer.seekTo(this.currentTime, true);
      } catch (e) {}
    }
    if (this.onTimeUpdate) {
      this.onTimeUpdate({
        current: this.currentTime,
        duration: this.duration,
        fraction: this.currentTime / this.duration
      });
    }
  }

  seekFraction(fraction) {
    this.seekTo(fraction * this.duration);
  }

  setPlayingState(on) {
    this.isPlaying = on;
    if (this.onPlayStateChange) {
      this.onPlayStateChange(on);
    }
  }

  /* ─────────────────────────────────────────────────────────────
     Beat & Time Tracking Loop
     ───────────────────────────────────────────────────────────── */

  startBeatClock() {
    if (this.timerId) return;

    let lastTick = performance.now();
    let accumulatedTime = 0;

    const tick = () => {
      if (!this.isPlaying) {
        this.timerId = null;
        return;
      }

      const now = performance.now();
      const dt = (now - lastTick) / 1000;
      lastTick = now;

      // Update current time from YouTube or fallback clock
      if (this.ytReady && this.ytPlayer && typeof this.ytPlayer.getCurrentTime === 'function') {
        try {
          const ytTime = this.ytPlayer.getCurrentTime();
          const ytDur = this.ytPlayer.getDuration();
          if (ytTime !== undefined && !isNaN(ytTime)) this.currentTime = ytTime;
          if (ytDur && !isNaN(ytDur) && ytDur > 0) this.duration = ytDur;
        } catch (e) {
          this.currentTime += dt;
        }
      } else {
        this.currentTime += dt;
        if (this.currentTime >= this.duration) {
          this.currentTime = 0;
          if (this.onTrackEnded) this.onTrackEnded();
        }
      }

      // Notify progress listeners
      if (this.onTimeUpdate) {
        this.onTimeUpdate({
          current: this.currentTime,
          duration: this.duration,
          fraction: this.duration > 0 ? this.currentTime / this.duration : 0
        });
      }

      // BPM Beat calculation
      accumulatedTime += dt;
      const beatSec = 60 / this.bpm;
      if (accumulatedTime >= beatSec) {
        accumulatedTime -= beatSec;
        this.beatIndex = (this.beatIndex + 1) % 4; // 4-beat bar for visual dots

        // Trigger procedural Dhol thumka on downbeats
        if (this.beatIndex === 0) {
          this.playDhol(0.25);
        } else if (this.beatIndex === 2) {
          this.playManjira(0.2);
        }

        if (this.onBeat) {
          this.onBeat({
            index: this.beatIndex,
            bpm: this.bpm,
            interval: beatSec
          });
        }
      }

      this.timerId = requestAnimationFrame(tick);
    };

    this.timerId = requestAnimationFrame(tick);
  }

  stopBeatClock() {
    if (this.timerId) {
      cancelAnimationFrame(this.timerId);
      this.timerId = null;
    }
  }
}

export const audio = new GarbaAudioEngine();
